rows = []
for sub_id, ar, en, roles, isic, hints in SUBS:
    main_id = sub_id.split(".")[0]
    main_ar, main_en, commercial = MAINS[main_id]
    role_list = [ROLE[c] for c in roles]
    rows.append({
        "main_id": main_id, "main_ar": main_ar, "main_en": main_en,
        "sub_id": sub_id, "sub_ar": ar, "sub_en": en,
        "primary_role": role_list[0] if role_list else "",
        "roles": "|".join(role_list),
        "sells": "yes" if ("wholesale" in role_list or "retail" in role_list) else "no",
        "buys": "yes" if commercial else "no",
        "commercial": "yes" if commercial else "no",
        "isic4_primary": isic.split("|")[0] if isic else "",
        "isic4_all": isic,
        "match_hints": hints,
    })

ids = [r["sub_id"] for r in rows]
dups = [i for i, c in Counter(ids).items() if c > 1]
assert not dups, f"duplicate sub_id: {dups}"

with open("farq_taxonomy.csv", "w", newline="", encoding="utf-8-sig") as f:
    w = csv.DictWriter(f, fieldnames=list(rows[0].keys()))
    w.writeheader(); w.writerows(rows)

with open("farq_taxonomy.json", "w", encoding="utf-8") as f:
    json.dump({
        "version": "2026-10-15",
        "isic_reference": "ISIC Rev.4 (4-digit class). Saudi national classification is ISIC4-based with 6-digit extensions; map 6-digit CR activities by their 4-digit prefix.",
        "roles": ROLE,
        "mains": [{"id": k, "ar": v[0], "en": v[1], "commercial": v[2]} for k, v in MAINS.items()],
        "subs": rows,
    }, f, ensure_ascii=False, indent=2)

c = Counter(r["main_id"] for r in rows)
print("subs:", len(rows), "mains:", len(MAINS))
for k in MAINS: print(f"  {k:9} {c[k]}")
isic_classes = set()
for r in rows:
    for x in r["isic4_all"].split("|"):
        if x: isic_classes.add(x)
print("distinct ISIC4 classes referenced:", len(isic_classes))
